// genType resolves namespaced references beside each generated file. Provide
// type-only aliases there without introducing runtime imports or a second API.
import { readdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
const root = path.resolve(import.meta.dirname, '..');
async function generatedFiles(directory) {
  const entries = await readdir(directory, { withFileTypes: true });
  const nested = await Promise.all(entries.map(entry => {
    const file = path.join(directory, entry.name);
    return entry.isDirectory() ? generatedFiles(file) :
      entry.name.endsWith('.gen.ts') && entry.name !== 'LightconeSdk.gen.ts' ? [file] : [];
  }));
  return nested.flat();
}
const files = (await Promise.all(['src', 'bindings'].map(dir => generatedFiles(path.join(root, dir))))).flat();
const modules = files.map(file => ({ name: path.basename(file, '.gen.ts'), file }))
  .sort((a, b) => b.name.length - a.name.length);
const aliases = new Map();
for (const file of files) {
  const original = await readFile(file, 'utf8');
  const content = original.replace(/[ \t]+$/gm, '');
  if (content !== original) await writeFile(file, content);
  const directory = path.dirname(file);
  for (const match of content.matchAll(/import type \{(\w+) as LightconeSdk_\w+\} from '\.\/LightconeSdk\.gen\.ts';/g)) {
    const imported = match[1];
    const owner = modules.find(module => imported.startsWith(`${module.name}_`));
    if (!owner) throw new Error(`No generated type owner for ${imported}`);
    const type = imported.slice(owner.name.length + 1);
    let target = path.relative(directory, owner.file).replaceAll(path.sep, '/');
    if (!target.startsWith('.')) target = `./${target}`;
    const exports = aliases.get(directory) ?? new Set();
    exports.add(`export type { ${type} as ${imported} } from '${target}';`);
    aliases.set(directory, exports);
  }
}
for (const [directory, exports] of aliases) {
  await writeFile(path.join(directory, 'LightconeSdk.gen.ts'),
    '// Generated by scripts/gentype-namespace.mjs. Type-only namespace aliases.\n' +
    [...exports].sort().join('\n') + '\n');
}
